B.aVt=new A.b5("\u0627\u0644\u0625\u062e\u0641\u0627\u0621","\u0627\u0644\u0646\u0648\u0646 \u0627\u0644\u0633\u0627\u0643\u0646\u0629 \u0623\u0648 \u0627\u0644\u062a\u0646\u0648\u064a\u0646 \u0642\u0628\u0644 \u0623\u062d\u062f \u062d\u0631\u0648\u0641 \u0627\u0644\u0625\u062e\u0641\u0627\u0621 \u0627\u0644\u062e\u0645\u0633\u0629 \u0639\u0634\u0631 \u062a\u064f\u0646\u0637\u0642 \u0628\u064a\u0646 \u0627\u0644\u0625\u0638\u0647\u0627\u0631 \u0648\u0627\u0644\u0625\u062f\u063a\u0627\u0645\u060c \u0645\u0639 \u063a\u064f\u0646\u0651\u0629.","\u0644\u0627 \u062a\u064f\u0638\u0647\u0631 \u0627\u0644\u0646\u0648\u0646 \u0628\u0648\u0636\u0648\u062d \u0648\u0644\u0627 \u062a\u064f\u062f\u063a\u0645\u0647\u0627\u061b \u0627\u062c\u0639\u0644\u0647\u0627 \u062e\u0641\u064a\u0641\u0629 \u0645\u0639 \u063a\u0646\u0629 \u0628\u0645\u0642\u062f\u0627\u0631 \u062d\u0631\u0643\u062a\u064a\u0646.")
B.aVk=new A.b5("Ikhfa (concealment)","A noon with sukoon or tanween before one of the fifteen ikhfa letters is pronounced between clear and merged, with ghunnah.","Neither say the noon fully nor merge it; keep it light with two counts of ghunnah.")
B.aVv=new A.b5("\u0627\u062e\u0641\u0627\u0621","\u0646\u0648\u0646 \u0633\u0627\u06a9\u0646 \u06cc\u0627 \u062a\u0646\u0648\u06cc\u0646 \u06a9\u06d2 \u0628\u0639\u062f \u0627\u062e\u0641\u0627\u0621 \u06a9\u06d2 \u067e\u0646\u062f\u0631\u06c1 \u062d\u0631\u0648\u0641 \u0645\u06cc\u06ba \u0633\u06d2 \u06a9\u0648\u0626\u06cc \u062d\u0631\u0641 \u0622\u0626\u06d2 \u062a\u0648 \u0627\u0633\u06d2 \u0627\u0638\u06c1\u0627\u0631 \u0627\u0648\u0631 \u0627\u062f\u063a\u0627\u0645 \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646 \u063a\u0646\u0651\u06c1 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u067e\u0691\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4","\u0646\u0648\u0646 \u06a9\u0648 \u0646\u06c1 \u067e\u0648\u0631\u0627 \u0638\u0627\u06c1\u0631 \u06a9\u0631\u06cc\u06ba \u0646\u06c1 \u0645\u062f\u063a\u0645 \u06a9\u0631\u06cc\u06ba\u061b \u06c1\u0644\u06a9\u0627 \u0631\u06a9\u06be\u06cc\u06ba \u0627\u0648\u0631 \u062f\u0648 \u062d\u0631\u06a9\u062a \u063a\u0646\u0651\u06c1 \u06a9\u0631\u06cc\u06ba\u06d4")
B.aUN=new A.b5("Ikhfa' (menyamarkan)","Nun sukun atau tanwin sebelum salah satu dari lima belas huruf ikhfa dibaca antara jelas dan lebur, disertai ghunnah.","Jangan membaca nun dengan jelas dan jangan meleburkannya; samarkan dengan dengung dua harakat.")
B.aVr=new A.b5("Ikhfa (dissimulation)","Le noun sakin ou le tanwin devant l'une des quinze lettres de l'ikhfa se prononce entre clair et fusionn\xe9, avec ghounna.","Ne prononcez pas le noun pleinement et ne le fusionnez pas ; gardez-le l\xe9ger avec deux temps de ghounna.")
B.aUM=new A.b5("\u0987\u0996\u09ab\u09be (\u0997\u09cb\u09aa\u09a8 \u0995\u09b0\u09be)","\u09b8\u09be\u0995\u09bf\u09a8 \u09a8\u09c2\u09a8 \u09ac\u09be \u09a4\u09be\u09a8\u09ac\u09c0\u09a8\u09c7\u09b0 \u09aa\u09b0\u09c7 \u0987\u0996\u09ab\u09be\u09b0 \u09aa\u09a8\u09c7\u09b0\u09cb\u099f\u09bf \u09b9\u09b0\u09ab\u09c7\u09b0 \u0995\u09cb\u09a8\u09cb\u099f\u09bf \u098f\u09b2\u09c7 \u09a4\u09be \u0987\u09af\u09b9\u09be\u09b0 \u0993 \u0987\u09a6\u0997\u09be\u09ae\u09c7\u09b0 \u09ae\u09be\u099d\u09be\u09ae\u09be\u099d\u09bf, \u0997\u09c1\u09a8\u09cd\u09a8\u09be\u09b9 \u09b8\u09b9 \u09aa\u09a1\u09bc\u09be \u09b9\u09af\u09bc\u0964","\u09a8\u09c2\u09a8 \u09aa\u09c1\u09b0\u09cb\u09aa\u09c1\u09b0\u09bf \u09b8\u09cd\u09aa\u09b7\u09cd\u099f\u0993 \u0995\u09b0\u09ac\u09c7\u09a8 \u09a8\u09be, \u09ae\u09bf\u09b6\u09bf\u09af\u09bc\u09c7\u0993 \u09ab\u09c7\u09b2\u09ac\u09c7\u09a8 \u09a8\u09be; \u09a6\u09c1\u0987 \u09b9\u09b0\u0995\u09a4 \u0997\u09c1\u09a8\u09cd\u09a8\u09be\u09b9 \u09b8\u09b9 \u09b9\u09be\u09b2\u0995\u09be \u09b0\u09be\u0996\u09c1\u09a8\u0964")
