B.aU6=new A.b5("\u0647\u0645\u0632\u0629 \u0627\u0644\u0648\u0635\u0644","\u062a\u064f\u0646\u0637\u0642 \u0639\u0646\u062f \u0627\u0644\u0628\u062f\u0621 \u0628\u0627\u0644\u0643\u0644\u0645\u0629\u060c \u0648\u062a\u0633\u0642\u0637 \u0639\u0646\u062f \u0648\u0635\u0644\u0647\u0627 \u0628\u0645\u0627 \u0642\u0628\u0644\u0647\u0627.","\u0625\u0630\u0627 \u0648\u0635\u0644\u062a \u0627\u0644\u0643\u0644\u0645\u0629 \u0628\u0645\u0627 \u0642\u0628\u0644\u0647\u0627 \u0641\u0644\u0627 \u062a\u0646\u0637\u0642 \u0627\u0644\u0647\u0645\u0632\u0629.")
B.aUt=new A.b5("Hamzat al-wasl (connecting hamza)","Pronounced when you start with the word, dropped when you join it to the word before.","When joining from the previous word, skip this hamza.")
B.aVh=new A.b5("\u06c1\u0645\u0632\u06c2 \u0648\u0635\u0644","\u06a9\u0644\u0645\u06d2 \u0633\u06d2 \u0627\u0628\u062a\u062f\u0627 \u06a9\u0631\u06cc\u06ba \u062a\u0648 \u067e\u0691\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u060c \u0627\u0648\u0631 \u067e\u0686\u06be\u0644\u06d2 \u06a9\u0644\u0645\u06d2 \u0633\u06d2 \u0645\u0644\u0627 \u06a9\u0631 \u067e\u0691\u06be\u06cc\u06ba \u062a\u0648 \u06af\u0631 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4","\u067e\u0686\u06be\u0644\u06d2 \u06a9\u0644\u0645\u06d2 \u0633\u06d2 \u0645\u0644\u0627 \u06a9\u0631 \u067e\u0691\u06be\u06cc\u06ba \u062a\u0648 \u06cc\u06c1 \u06c1\u0645\u0632\u06c1 \u0646\u06c1 \u067e\u0691\u06be\u06cc\u06ba\u06d4")
B.aUK=new A.b5("Hamzah Washal","Dibaca ketika memulai dari kata itu, dan gugur ketika disambung dengan kata sebelumnya.","Jika menyambung dari kata sebelumnya, jangan baca hamzah ini.")
B.aUC=new A.b5("Hamzat al-wasl (hamza de liaison)","Elle se prononce quand on commence par le mot, et tombe quand on le lie au mot pr\xe9c\xe9dent.","Si vous liez depuis le mot pr\xe9c\xe9dent, ne prononcez pas cette hamza.")
